#include "vkaether/vk_api.hpp"
#include <curl/curl.h>
#include <mutex>
#include <stdexcept>
namespace vkaether {
namespace {std::once_flag once;void init(){curl_global_init(CURL_GLOBAL_DEFAULT);}size_t write_cb(char*p,size_t s,size_t n,void*u){auto z=s*n;static_cast<std::string*>(u)->append(p,z);return z;}}
VkApi::VkApi(std::string t,std::string v):token_(std::move(t)),version_(std::move(v)){std::call_once(once,init);}
std::string VkApi::http_get(std::string_view url){CURL*c=curl_easy_init();if(!c)throw std::runtime_error("curl init failed");std::string body;std::string u(url);curl_easy_setopt(c,CURLOPT_URL,u.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_cb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&body);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,10L);curl_easy_setopt(c,CURLOPT_TIMEOUT,35L);curl_easy_setopt(c,CURLOPT_NOSIGNAL,1L);curl_easy_setopt(c,CURLOPT_TCP_KEEPALIVE,1L);auto rc=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_easy_cleanup(c);if(rc!=CURLE_OK)throw std::runtime_error(curl_easy_strerror(rc));if(status<200||status>=300)throw std::runtime_error("HTTP status "+std::to_string(status));return body;}
nlohmann::json VkApi::call(std::string_view method,const nlohmann::json& params)const{CURL*c=curl_easy_init();if(!c)throw std::runtime_error("curl init failed");std::string form;auto add=[&](const std::string&k,const std::string&v){char*e=curl_easy_escape(c,v.c_str(),static_cast<int>(v.size()));if(!e)throw std::runtime_error("URL encode failed");if(!form.empty())form+='&';form+=k+'='+e;curl_free(e);};for(auto i=params.begin();i!=params.end();++i)add(i.key(),i.value().is_string()?i.value().get<std::string>():i.value().dump());add("access_token",token_);add("v",version_);std::string url="https://api.vk.com/method/"+std::string(method),body;curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_POST,1L);curl_easy_setopt(c,CURLOPT_POSTFIELDS,form.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_cb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&body);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,10L);curl_easy_setopt(c,CURLOPT_TIMEOUT,20L);curl_easy_setopt(c,CURLOPT_NOSIGNAL,1L);auto rc=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_easy_cleanup(c);if(rc!=CURLE_OK)throw std::runtime_error(curl_easy_strerror(rc));if(status<200||status>=300)throw std::runtime_error("VK HTTP status "+std::to_string(status));auto j=nlohmann::json::parse(body);if(j.contains("error"))throw std::runtime_error("VK API error: "+j["error"].dump());return j.at("response");}
}